// Üretilen dosya: tool/ozgun/uret.py. Doğa · Memeliler ayrıntılı (zor).
const ozNature6Zor = <(String, String, List<String>, String)>[
  ('Sürüngen atalarda çene ekleminde yer alan iki kemik, memelilerin evriminde hangi yapıya dönüşmüştür?', 'Çekiç ve örs kemikçiklerine', ['Köprücük kemiği ile kürek kemiğine', 'Dil kemiği ile gırtlak kıkırdağına', 'İlk iki boyun omuruna'], 'Sürüngenlerdeki eklem ve kare kemikleri memelilerde orta kulağa geçerek çekiç ve örs olmuştur; bu dönüşüm fosillerde ve embriyolarda izlenebilir.'),
  ('Memelilerin büyük çoğunluğunda dişler ömür boyunca yalnızca bir kez değişir: önce süt dişleri, sonra kalıcı dişler çıkar. Bu özelliğe ne ad verilir?', 'Difiodontluk', ['Homodontluk', 'Polifiodontluk', 'Tekodontluk'], 'Difiodont hayvanlarda iki diş takımı (süt ve kalıcı) bulunur. Köpek balıkları ve birçok sürüngen gibi dişlerini sürekli yenileyenler polifiodonttur.'),
  ('Memelilerin çoğunda boyun omuru sayısı yedidir. Bu kurala uymayan iyi bilinen gruplardan biri hangisidir?', 'Tembel hayvanlar', ['Zürafalar', 'Afrika filleri', 'Yaban atları'], 'Zürafa dahil memelilerin neredeyse tamamında yedi boyun omuru vardır; tembel hayvanların bazı türleri ve deniz inekleri bu kuralın bilinen istisnalarıdır.'),
  ('Memelileri ve onların soyu tükenmiş akrabalarını içeren, kafatasında göz çukurunun arkasında tek bir şakak açıklığı bulunan omurgalı grubuna ne ad verilir?', 'Sinapsitler', ['Diapsitler', 'Anapsitler', 'Arkozorlar'], 'Sinapsitlerde göz arkasında tek şakak deliği bulunur; memeliler bu soyun günümüze ulaşan tek koludur. Kuşlar ve sürüngenlerin çoğu diapsittir.'),
  ('Yumurtadan çıkan ekidne yavrusuna ne ad verilir?', 'Puggle', ['Joey', 'Kit', 'Calf'], 'Ekidne ve ornitorenk yavruları için İngilizcede \'puggle\' adı kullanılır. \'Joey\' kanguru yavrusunu anlatır.'),
  ('Monotremlerin vücut sıcaklığı hakkında hangisi doğrudur?', 'Diğer memelilerin çoğundan biraz düşüktür', ['Kuşlarınkinden belirgin biçimde yüksektir', 'Her zaman çevre sıcaklığıyla aynıdır', 'Gün içinde düzenli olarak 20 °C dalgalanır'], 'Ornitorenk ve ekidnelerin vücut sıcaklığı yaklaşık 30–32 °C dolayındadır; bu değer plasentalı memelilerin çoğundan düşüktür ama yine de sıcakkanlıdırlar.'),
  ('Kırmızı kanguru yüksek hızlarda sıçrarken neden fazla enerji harcamaz?', 'Arka bacak tendonları her sıçrayışta enerjiyi yay gibi depolayıp geri verir', ['Sıçrarken soluk almayı tamamen durdurur', 'Kuyruğunu pervane gibi döndürerek itme kuvveti üretir', 'Kasları yalnızca anaerobik yolla çalışır'], 'Kangurunun uzun Aşil tendonları esnek enerji depolar; bu sayede belirli bir hızın üstünde hız artsa da enerji harcaması çok az artar.'),
  ('Avustralya çöllerinde kumun içinde yaşayan, gözleri derinin altında körelmiş ve kumu yüzer gibi kazan keseli hangisidir?', 'Keseli köstebek', ['Numbat', 'Kuoka', 'Uzun burunlu bandikut'], 'Keseli köstebekler çöl kumunda yaşar; görünüşleri Afrika\'nın altın köstebeklerine çok benzese de akraba değildir.'),
  ('Koalanın yavrusu sütten kesilmeden önce annesinin özel bir dışkısını (pap) yer. Bunun yararı nedir?', 'Okaliptüs yaprağını sindirecek bağırsak mikroplarını almak', ['Annesinin kokusunu öğrenip onu kalabalıkta tanımak', 'Dişlerinin daha hızlı çıkmasını sağlamak', 'Kesenin içini temizleyerek enfeksiyonu önlemek'], 'Pap, annenin bağırsağındaki mikroplarla zengindir; yavru bu mikropları alarak sert ve zehirli okaliptüs yapraklarını sindirmeye hazırlanır.'),
  ('Afrotheria adlı memeli grubu hangi ortak özelliğe göre tanımlanmıştır?', 'Afrika kökenli ortak bir atadan geldiklerini gösteren DNA verileri', ['Tümünün hortum ya da uzamış bir burun taşıması', 'Tümünün termit ve karıncayla beslenmesi', 'Tümünün yarı sucul bir yaşam sürmesi'], 'Filler, deniz inekleri, damanlar, yer domuzu, tenrekler ve altın köstebekler dış görünüşleri çok farklı olsa da moleküler verilerle Afrika kökenli tek bir soy oluşturur.'),
  ('Dokuz bantlı armadillonun üremesindeki olağan dışı özellik hangisidir?', 'Tek bir döllenmiş yumurtadan genetik olarak özdeş dördüzler doğurması', ['Yumurta bırakıp kuluçkaya yatması', 'Yavrularını kesede taşıması', 'Dişilerinin hiç süt vermemesi'], 'Dokuz bantlı armadilloda tek embriyo dörde bölünür; bu nedenle aynı batındaki dört yavru tek yumurta dördüzleridir.'),
  ('Bir doğa belgeselinde tehlike anında kendini tam bir top hâline getirebilen armadillo gösteriliyor. Bu türün hangisi olması en olasıdır?', 'Üç bantlı armadillo', ['Dokuz bantlı armadillo', 'Dev armadillo', 'Pembe peri armadillosu'], 'Yalnızca üç bantlı armadillolar zırhlarını kapatarak tam bir top olabilir; dokuz bantlı armadillo gibi diğer türler kaçmayı ya da kazmayı tercih eder.'),
  ('Fillerin azı dişleri ömür boyunca nasıl yenilenir?', 'Arkadan öne kayan ardışık takımlarla', ['Her yıl tümü birden dökülüp alttan yenileri çıkarak', 'Hiç yenilenmez, doğumdaki dişlerle ömür boyu yaşanır', 'Köpek balıkları gibi sınırsız sayıda yedek dişle'], 'Fillerde her çene yarısında ömür boyunca altı azı dişi sırayla kullanılır; aşınan diş öne itilip düşer ve arkadaki yerine geçer.'),
  ('Erkek fillerde dönemsel olarak testosteron düzeyinin çok yükseldiği, şakak bezlerinden salgı aktığı ve saldırganlığın arttığı duruma ne ad verilir?', 'Musth', ['Östrus', 'Kızgınlık uykusu', 'Flehmen'], 'Musth, erkek fillerde görülen hormonal bir dönemdir; şakak bezlerinden koyu bir salgı akar ve fil daha saldırgan olur. Östrus ise dişilere ait kızgınlık dönemidir.'),
  ('Zürafa başını su içmek için aşağı indirdiğinde beyninin aşırı kan basıncından korunmasına yardımcı olan yapılar hangileridir?', 'Toplardamar kapakçıkları ve beyin tabanındaki damar ağı', ['Kafatasındaki geniş ve çok odacıklı hava boşlukları', 'Uzun dilinin içinde fazla kanı depolayabilmesi', 'Boynuz çıkıntılarındaki kanı soğutan geniş ve kıvrımlı damarlar'], 'Zürafada boyun toplardamarlarındaki kapakçıklar kanın geri akışını engeller; beyin tabanındaki ince damar ağı (rete mirabile) basınç değişimini yumuşatır.'),
  ('Develerin alyuvarları diğer memelilerinkinden hangi biçim özelliğiyle ayrılır?', 'Oval biçimlidir', ['Çekirdekli ve yuvarlaktır', 'Yıldız biçimlidir', 'İki kat büyük ve küreseldir'], 'Devegillerin alyuvarları memeliler arasında olağan dışı biçimde ovaldir; bu yapı susuz kalındığında kanın akıcılığını korumaya ve hızla su içildiğinde hücrelerin patlamamasına yardımcı olur.'),
  ('Uzun süre susuz kalmış bir deve su bulduğunda kısa sürede çok büyük miktarda su içebilir. Bu hızlı su alımına dayanabilmesi neyle ilişkilidir?', 'Alyuvarlarının şişmeye dayanıklı olmasıyla', ['Hörgücünün bir su deposu gibi hızla dolmasıyla', 'Midesinin fazla suyu hemen dışarı atmasıyla', 'Kanının neredeyse hiç su içermemesiyle'], 'Başka memelilerde aniden çok su içmek alyuvarları şişirip patlatabilir; devenin oval alyuvarları bu şişmeye dayanıklıdır. Hörgüç su değil yağ depolar.'),
  ('Üç zebra türü arasında en iri olanı, ince ve sık çizgileri ve büyük yuvarlak kulaklarıyla tanınan tür hangisidir?', 'Grevy zebrası', ['Ova zebrası', 'Dağ zebrası', 'Somali yaban eşeği'], 'Kenya ve Etiyopya\'da yaşayan Grevy zebrası yaşayan en büyük yabani at türüdür; çizgileri ova zebrasınınkinden daha ince ve sıktır.'),
  ('Bugünkü evcil atların büyük çoğunluğunun soyu, genetik çalışmalara göre yaklaşık MÖ 2200 dolaylarında hangi bölgede evcilleştirilmiş atlara dayanır?', 'Volga-Don arasındaki Karadeniz kuzeyi bozkırları', ['Nil Vadisi ve Mısır\'ın verimli deltası', 'Arap Yarımadası\'nın iç kesimlerindeki vahalar', 'İber Yarımadası\'nın güney kıyı ovaları'], 'Antik DNA çalışmaları bugünkü evcil atların kökenini Volga ve Don nehirleri arasındaki bozkırlara bağlamış, bu atların oradan hızla Avrasya\'ya yayıldığını göstermiştir.'),
  ('Yaşayan gergedanlar içinde en küçüğü olan, vücudu seyrek kıllarla örtülü ve iki boynuzlu tür hangisidir?', 'Sumatra gergedanı', ['Cava gergedanı', 'Hint gergedanı', 'Afrika siyah gergedanı'], 'Sumatra gergedanı yaşayan gergedanların en küçüğüdür ve kıllı derisiyle soyu tükenmiş yünlü gergedana en yakın akrabadır.'),
  ('Afrika\'da yaşayan siğilli domuzlar otlarken çoğu zaman nasıl bir duruş alır?', 'Ön bacaklarının dizleri üzerine çöker', ['Arka bacakları üzerinde dimdik ayağa kalkar', 'Yan yatarak otlar', 'Başını sırtına çevirerek otlar'], 'Kısa boyunlu siğilli domuz, kısa otlara ulaşmak için ön dizleri üzerine çöküp otlar; dizlerinde bu duruşa uygun nasırlaşmış deri bulunur.'),
  ('Kuzey Amerika\'da yaşayan çatal boynuzlu antilobun (pronghorn) boynuzlarını diğer boynuzlu hayvanlardan ayıran özellik hangisidir?', 'Keratin kılıfın her yıl dökülüp yenilenmesi', ['Boynuzların tamamen kemikten yapılıp her yıl düşmesi', 'Boynuzların yalnızca dişilerde bulunması', 'Boynuzların burun üzerinde yer alması'], 'Çatal boynuzlu antilobun kemik özü kalıcıdır ama keratin kılıfı her yıl dökülür; bu özellik onu hem geyiklerden hem de sığırgillerden ayırır.'),
  ('Tibet Platosu\'nun soğuk ve oksijeni az ortamında yaşayan yak\'ın bilimsel adının (Bos grunniens) \'homurdanan\' anlamına gelmesinin nedeni nedir?', 'Böğürmek yerine homurtuya benzer sesler çıkarması', ['Gevişini getirirken sürekli dişlerini gıcırdatması', 'Karda yürürken ayak eklemlerinden sesler gelmesi', 'Soluk alırken burnundan ıslık sesi çıkması'], 'Yaklar sığırlar gibi böğürmez; daha çok derinden gelen homurtu benzeri sesler çıkarır ve adını buradan alır.'),
  ('Görünüşü sığıra benzeyen misk öküzü, moleküler ve anatomik verilere göre sığırgiller içinde hangi hayvanlara daha yakındır?', 'Keçi ve koyunlara', ['Bizon ve yaklara', 'Geyik ve ren geyiklerine', 'Su mandalarına'], 'Misk öküzü adına karşın sığırların değil, keçi ve koyunların yer aldığı alt familyanın (Caprinae) üyesidir.'),
  ('Amerikan bizonu ile Avrupa bizonu karşılaştırıldığında Avrupa bizonu için hangisi doğrudur?', 'Daha uzun bacaklı ve orman yaşamına daha uyumludur', ['Erkeklerinde bile boynuz bulunmaz', 'Omuz hörgücü Amerikan bizonununkinden çok daha büyüktür', 'Yalnızca kıyı bataklıklarında yaşar'], 'Avrupa bizonu (wisent) daha uzun bacaklı, ormanda yaprak ve dallarla da beslenen bir türdür; Amerikan bizonu ise açık otlaklara uyumlu, kocaman omuzlu bir otlayıcıdır.'),
  ('Karacalarda yaz ortasında çiftleşme olsa da yavru ertesi bahar doğar. Bunun nedeni nedir?', 'Embriyonun tutunmasının aylarca gecikmesi', ['Gebeliğin on iki ay sürmesi', 'Spermin dişinin üreme kanalında kış boyunca canlı saklanması', 'Yavrunun kış boyunca yumurta içinde kalması'], 'Karaca, çift toynaklılar arasında gecikmeli tutunma gösteren nadir türlerdendir; embriyo kış ortasına kadar dinlenir, sonra gelişmeye başlar ve yavru elverişli baharda doğar.'),
  ('Ren geyiklerinin gözlerindeki yansıtıcı tabakanın (tapetum) kışın maviye dönmesinin bilinen işlevi nedir?', 'Karanlıkta ışığa duyarlılığı artırmak', ['Kar yüzeyinden yansıyan ışığı tümüyle engellemek', 'Göz küresini soğuktan yalıtmak', 'Erkeklerin dişileri uzaktan tanıması'], 'Kışın tapetum rengi altından maviye döner; bu değişim retinaya daha çok ışığın geri yansımasını sağlayarak karanlık kış aylarında görmeyi kolaylaştırır.'),
  ('Ren geyikleri yürürken dizlerinden tıkırtı sesi gelir. Bu sesin sürü için olası işlevi nedir?', 'Tipide sürü üyelerinin birbirini izlemesi', ['Yaklaşan kurtları ürküterek kaçırmak', 'Karı sıkıştırarak sürüye yol açmak', 'Yavrulara emme zamanını haber vermek'], 'Ayaktaki bir tendonun kemik üzerinden kaymasıyla oluşan tıkırtının, sürü üyelerinin kar fırtınasında birbirine yakın kalmasına yardım ettiği düşünülür.'),
  ('Afrika çöllerinde yaşayan oriksler gündüz vücut ısısının yükselmesine izin verir. Bunun yanında beynini aşırı ısınmadan koruyan uyumu hangisidir?', 'Beyne giden kanı soğutan damar ağı', ['Beynin her gün birkaç saat çalışmayı durdurması', 'Kafatası boşluklarının suyla dolu olması', 'Boynuzların ısıyı emip depolaması'], 'Orikslerde beyin tabanındaki damar ağında atardamar kanı, burunda buharlaşmayla soğuyan toplardamar kanıyla ısı alışverişi yapar; böylece beyin vücuttan daha serin kalır.'),
  ('Biyolojik sınıflandırma açısından \'antilop\' kavramı hakkında hangisi doğrudur?', 'Ortak atalı resmî bir grup değil, gündelik bir addır', ['Geyikgillerin bir alt familyasıdır', 'Atlarla akraba olan ayrı bir takımdır', 'Yalnızca Afrika\'daki tek bir cinsi kapsar'], 'Antilop, sığır, keçi ve koyun dışında kalan çeşitli sığırgil soylarına verilen gündelik bir addır; bu soylar tek bir ortak ataya sahip ayrı bir grup oluşturmaz.'),
  ('Afrika yaban köpeği sürülerinde avdan dönen bireylerin yuvadaki yavrulara ve bakıcılara besin vermesi nasıl gerçekleşir?', 'Midelerindeki eti kusarak', ['Eti parçalar hâlinde ağızlarında taşıyarak', 'Avın bütününü yuvaya sürükleyerek', 'Yalnızca dişilerin sütüyle besleyerek'], 'Avcılar yuttukları eti yuvada kusarak yavrulara ve yuvada kalan erişkinlere paylaştırır; bu, sürü içi iş birliğinin bir örneğidir.'),
  ('Doğu Asya kökenli olup Avrupa\'ya kürk için getirilen, köpekgiller içinde kış uykusuna benzer bir dinlenme dönemine girebilen tek tür hangisidir?', 'Rakun köpeği', ['Altın çakal', 'Kutup tilkisi', 'Kızıl tilki'], 'Rakun köpeği rakuna benzese de köpekgildir; soğuk kışlarda yuvasında uzun süre uyuşuk hâlde kalan tek köpekgil olarak bilinir.'),
  ('Aslan, kaplan, leopar ve jaguarın kükreyebilmesi neyle ilişkilidir?', 'Esnek bir dil kemiği düzeneği', ['Akciğerlerinin diğer kedilerden çok büyük olması', 'Ağızlarında ses odası bulunması', 'Dişlerinin sayısının fazla olması'], 'Panthera cinsindeki büyük kedilerde dil kemiği düzeneği esnek bağlarla tutunur ve uzun ses telleri vardır; bu yapı derin kükremeyi mümkün kılar. Ev kedisi gibi küçük kediler ise mırlar.'),
  ('Kedilerin tatlı tadı algılayamamasının nedeni nedir?', 'Tatlı reseptör geninin bozuk olması', ['Dillerinde hiç tat tomurcuğu bulunmaması', 'Şekerin midelerinde zehirli olması', 'Burunlarının tat almayı baskılaması'], 'Kedilerde tatlı tat reseptörünün bir alt birimini kodlayan gen işlevsizdir; et ağırlıklı beslenen bu hayvanlar için tatlıyı algılamak gerekli değildir.'),
  ('Aslan sürüsünü ele geçiren yeni bir erkeğin, sürüdeki küçük yavruları öldürmesi evrimsel olarak nasıl açıklanır?', 'Dişilerin erken kızgınlığa girmesi', ['Sürünün toplam besin ihtiyacını azaltmak', 'Yavrulardan bulaşıcı hastalık kapmamak', 'Yaşlı dişileri sürüden kovmak'], 'Emziren dişi yeniden kızgınlığa girmez; yavrular ölünce dişi kısa sürede yeniden çiftleşebilir ve yeni erkek kendi genlerini aktarma fırsatı bulur.'),
  ('Hindistan\'da yaşayan tembel ayının (dudaklı ayı) termit yuvalarından böcekleri emerek beslenmesine yardım eden özellik hangisidir?', 'Üst kesici dişlerinin eksik olması', ['Hortum biçiminde uzamış bir burnu olması', 'Yapışkan salgı üreten ayak tabanları', 'Dala tutunan kancalı uzun bir kuyruğu'], 'Tembel ayıda üst kesici dişlerden ikisi eksiktir; bu boşluk ve kapatılabilen burun delikleri sayesinde termitleri güçlü bir emişle ağzına çeker.'),
  ('Ayılar aylarca süren kış dinlenmesinde idrar yapmadıkları hâlde kanlarında zehirli üre birikmez. Bunun nedeni nedir?', 'Üre azotunu geri kazanmaları', ['Böbreklerinin kış boyunca tamamen durması', 'Ürenin ter bezleriyle dışarı atılması', 'İn duvarını yalayıp mineral almaları'], 'Kış dinlenmesindeki ayılar ürenin azotunu geri kazanıp yeniden amino asit ve protein yapımında kullanır; böylece kas kaybı da sınırlı kalır.'),
  ('Kuzey ormanlarında ve tundrada yaşayan, sansargillerin karada yaşayan en iri temsilcisi olup karda kendinden büyük avları ve leşleri değerlendiren hayvan hangisidir?', 'Kutup porsuğu', ['Amerikan vizonu', 'Gelincik', 'Ağaç sansarı'], 'Kutup porsuğu (Gulo gulo) iri yapısı, güçlü çenesi ve geniş ayaklarıyla karda rahat hareket eder; yaz dahil depoladığı leşleri soğukta saklar.'),
  ('Kokarcaların biyolojik sınıflandırmadaki yeri hakkında hangisi doğrudur?', 'Ayrı bir familya oluştururlar', ['Sansargillerin bir alt türüdürler', 'Kemirgenler takımında yer alırlar', 'Amerika\'ya özgü keseli memelilerdir'], 'Eskiden sansargillere dahil edilen kokarcalar, genetik çalışmalar sonucunda ayrı bir familya (Mephitidae) olarak sınıflandırılmıştır.'),
  ('Bazı mangust türlerinin zehirli yılanlarla baş edebilmesinin bilinen fizyolojik nedeni hangisidir?', 'Reseptörlerinin zehri az bağlaması', ['Kanlarında zehri parçalayan bakteriler bulunması', 'Derilerinin dişlerin geçemeyeceği kalınlıkta olması', 'Her ısırıkta zehre yeniden bağışıklık kazanmaları'], 'Mangustların sinir-kas kavşağındaki asetilkolin reseptöründe yılan nörotoksinlerinin bağlanmasını zorlaştıran değişiklikler bulunur.'),
  ('Güneydoğu Asya\'da yaşayan binturong adlı misk kedisinin kokusu hangi gıdaya benzetilir?', 'Patlamış mısır', ['Çürümüş yumurta', 'Taze çekilmiş kahve', 'Limon kabuğu'], 'Binturongun koku işaretlerinde, patlamış mısıra kokusunu veren 2-asetil-1-pirolin adlı bileşik bulunur.'),
  ('Avrupa\'nın ormanlarında yaşayan ve uzun kış uykusuyla ünlü olan, Roma döneminde besi hayvanı olarak toprak kaplarda beslenen kemirgen hangisidir?', 'Yediuyur', ['Gri sincap', 'Hamster', 'Tarla faresi'], 'Yediuyur (Glis glis) yılın yarısından fazlasını kış uykusunda geçirebilir; adı da bu uzun uykudan gelir. Romalılar onu özel kaplarda besleyip yerdi.'),
  ('Brezilya cevizinin çok sert meyve kabuğunu açarak tohumları yayan ve bazılarını gömüp unutarak ağacın yenilenmesine katkı sağlayan kemirgen hangisidir?', 'Aguti', ['Kapibara', 'Çinçilla', 'Kunduz'], 'Agutiler güçlü kesici dişleriyle Brezilya cevizinin kabuğunu açabilen az sayıdaki hayvandandır; gömüp unuttukları tohumlar yeni fidanlara dönüşür.'),
  ('Laboratuvar sıçanları gıdıklandığında insan kulağının duyamadığı yüksek frekanslı sesler çıkarır. Bu bulgu en çok neyin araştırılmasına katkı sağlamıştır?', 'Hayvanlarda olumlu duyguların', ['Sıçanların ekolokasyon kullanmasının', 'Sıçanların renk görmesinin', 'Sıçanların kış uykusunun'], 'Jaak Panksepp\'in çalışmalarında gıdıklanan sıçanların yaklaşık 50 kHz\'lik ultrasonik sesler çıkarması, oyun ve olumlu duyguların sinirsel temellerinin incelenmesinde kullanılmıştır.'),
  ('Evcil altın hamsterların büyük çoğunluğunun soyu nereye dayanır?', '1930\'da Halep çevresinde yakalanan küçük bir aileye', ['Çin\'de binlerce yıl önce evcilleştirilen yabani hamsterlara', 'Avrupa\'nın tarla hamsterlarına', 'Kuzey Amerika\'nın çöl farelerine'], 'Suriye hamsteri 1930\'da Halep yakınında yakalanan bir dişi ve yavrularından laboratuvarda çoğaltılmış, evcil hamsterların çoğu bu küçük gruptan türemiştir.'),
  ('Erkek ev farelerinin dişilere kur yaparken çıkardığı ve karmaşık yapısı nedeniyle \'şarkı\' olarak nitelenen sesler hangi frekans aralığındadır?', 'Ultrasonik, insan kulağının üstünde', ['İnfrasonik, insan kulağının altında', 'İnsan konuşmasıyla aynı aralıkta', 'Kuş ötüşüyle aynı aralıkta'], 'Erkek farelerin kur sesleri büyük ölçüde ultrasoniktir; özel mikrofonlarla kaydedilip yavaşlatıldığında hece benzeri dizilerden oluştuğu görülür.'),
  ('Avrupa\'daki bazı sivri farelerde kış yaklaşırken kafatası ve beyin hacminin küçüldüğü, baharda kısmen yeniden büyüdüğü gözlenmiştir. Bu olayın olası yararı nedir?', 'Besinin kıt olduğu kışın enerji ihtiyacını azaltmak', ['Kış uykusunda daha derin uyumak', 'Kar altında daha hızlı kazmak', 'Yavrulara daha çok süt vermek'], 'Dehnel olayı denen bu değişim, beyin gibi enerji tüketen dokuları küçülterek kış boyunca hayatta kalmayı kolaylaştırır; sivri fareler kış uykusuna yatmaz.'),
  ('Yarasalar vücut büyüklüklerine göre beklenenden çok daha uzun yaşar. Örneğin bir Brandt yarasasının yaklaşık kaç yıl yaşadığı kaydedilmiştir?', '40 yıldan fazla', ['3 yıl kadar', '10 yıl kadar', '100 yıldan fazla'], 'Birkaç gram ağırlığındaki Brandt yarasasının doğada 40 yılı aşkın yaşadığı belgelenmiştir; aynı boyuttaki kemirgenler genellikle birkaç yıl yaşar.'),
  ('Vampir yarasaların avlarının derisinde kanın yüzeye yakın olduğu yeri bulmalarına yardım eden duyu hangisidir?', 'Burun çevresindeki ısı algılayıcılar', ['Kulaklarındaki manyetik alan alıcıları', 'Gözlerindeki ultraviyole görme yeteneği', 'Kanat zarlarındaki tat alıcıları'], 'Vampir yarasaların burnundaki özel çukurlarda bulunan ısıya duyarlı sinir uçları, derideki sıcak kan damarlarının yerini kızılötesi ısıdan algılamalarını sağlar.'),
  ('Kuzey Amerika\'da yaşayan kısa kuyruklu sivri farenin tükürüğünü olağan dışı kılan özellik hangisidir?', 'Avını felç eden zehir içermesi', ['Karanlıkta ışık saçması', 'Kanı anında pıhtılaştırması', 'Toprağı eritip yumuşatması'], 'Kuzey kısa kuyruklu sivri faresinin tükürük bezleri, solucan ve böcek gibi avları felç eden bir zehir üretir; felçli avlar canlı olarak depolanabilir.'),
  ('Karayip adalarında yaşayan solenodonları memeliler arasında özel kılan özellik hangisidir?', 'Alt kesici dişlerindeki oluktan zehir akıtmaları', ['Yumurta bırakıp kuluçkaya yatmaları', 'Deri zarıyla süzülerek uçabilmeleri', 'Kürklerinde fotosentez yapan alg taşımaları'], 'Solenodonların alt kesici dişlerinde zehri avına ileten bir oluk bulunur; bu, yılanlardakine benzeyen ve memelilerde nadir görülen bir yapıdır.'),
  ('Lemurlar ve lorisler \'ıslak burunlu\' primatlar olarak gruplanır. Bu grubun alt çenesindeki ön dişlerin öne doğru dizilerek oluşturduğu yapı ne işe yarar?', 'Kürkü taramak ve tımar yapmak', ['Ağaç kabuğunu kesip reçine içmek', 'Avının kafatasını delmek', 'Toprağı kazmak'], 'Islak burunlu primatların alt kesici ve köpek dişleri dar bir tarak gibi öne uzanır; bu diş tarağı tımarda ve bazı türlerde ağaç özsuyunu kazımada kullanılır.'),
  ('Etiyopya yaylalarında yaşayan ve beslenmesinin büyük bölümünü ot oluşturan primat hangisidir?', 'Gelada', ['Mandril', 'Hortumlu maymun', 'Kapuçin'], 'Geladalar besinlerinin çoğunu ot yaprakları ve tohumlarından sağlayan tek primatlardır; göğüslerindeki kırmızı çıplak deri nedeniyle \'kanayan kalp maymunu\' diye de anılır.'),
  ('İnsanda 46, şempanze, goril ve orangutanda ise 48 kromozom bulunur. Bu farkın en iyi açıklaması hangisidir?', 'İki atasal kromozomun kaynaşması', ['Büyük insansıların sonradan iki kromozom kazanması', 'İnsanın iki kromozomunu tümüyle kaybetmesi', 'Kromozom sayısının tür içinde rastgele değişmesi'], 'İnsanın 2. kromozomu, diğer büyük insansılarda ayrı duran iki kromozomun uç uca kaynaşmasıyla oluşmuştur; kromozom üzerindeki kalıntı yapılar bunu doğrular.'),
  ('Orangutanlarda bir dişinin iki doğumu arasında geçen süre genellikle ne kadardır?', 'Yaklaşık 7-8 yıl', ['Yaklaşık 1 yıl', 'Yaklaşık 2-3 yıl', 'Yaklaşık 15 yıl'], 'Orangutan yavruları uzun süre annelerinden öğrenir; dişiler yaklaşık 7-8 yılda bir doğurur ve bu, memeliler arasında en uzun doğum aralıklarındandır.'),
  ('Beyaz kürklü bir hayvanın albino değil lösistik olduğunu anlamak için hangi özelliğe bakılabilir?', 'Gözlerinin koyu renkli olmasına', ['Kürkünün baştan sona beyaz olmasına', 'Güneşte derisinin kolayca yanmasına', 'Kulak kepçelerinin büyük olmasına'], 'Lösizmde pigment hücreleri kürk ve deride eksiktir ama gözler normal renktedir; albinizmde ise melanin hiç yapılamadığı için gözler de pembe-kırmızıdır.'),
  ('Memelilerde toplam bazal metabolizma hızının vücut kütlesinin yaklaşık 3/4 kuvvetiyle orantılı olduğu kabul edilir (Kleiber yasası). Kütlesi bir başkasının 16 katı olan bir memelinin toplam metabolizma hızı yaklaşık kaç katıdır?', '8 katı', ['4 katı', '12 katı', '16 katı'], '16^(3/4) = (16^(1/4))^3 = 2^3 = 8 bulunur; toplam enerji harcaması kütle kadar değil, daha yavaş artar.'),
  ('Kleiber yasasına göre memelilerde birim kütle başına metabolizma hızı kütlenin −1/4 kuvvetiyle orantılıdır. 1 kg\'lık bir tavşan ile 16 kg\'lık bir köpek karşılaştırıldığında köpeğin her kilogram dokusu tavşanınkinin yaklaşık ne kadarı enerji harcar?', 'Yarısı', ['Dörtte biri', 'Aynısı', 'İki katı'], '16^(−1/4) = 1/2 olduğundan köpeğin kilogram başına metabolizması tavşanınkinin yaklaşık yarısıdır.'),
  ('Koyunlar genellikle sonbaharda günler kısalırken, atlar ise ilkbaharda günler uzarken kızgınlığa girer. Bu iki türün yavrularının da ilkbaharda doğmasını sağlayan etken nedir?', 'Gebelik sürelerinin farklı olması', ['İki türün de kışın gebeliği durdurması', 'Yavruların doğumu kendi istedikleri zaman başlatması', 'Atların gebeliğinin birkaç hafta sürmesi'], 'Koyunun gebeliği yaklaşık 5 ay, atınki yaklaşık 11 ay sürer; sonbaharda çiftleşen koyun ve ilkbaharda çiftleşen at, yavrularını ertesi ilkbaharda dünyaya getirir.'),
  ('Kara ve deniz memelileri arasında süt yağı oranı en yüksek olanlardan biri, sütünde yağ oranı yüzde 60 dolayına ulaşabilen kapüşonlu foktur. Bu çok yağlı sütün işlevi nedir?', 'Yavrunun hızla yağ kazanması', ['Sütün buzda donmasını engellemek', 'Annenin daha az su içmesini sağlamak', 'Yavrunun kemiklerini sertleştirmek'], 'Kapüşonlu fok yavrusu buz üzerinde yalnızca yaklaşık dört gün emzirilir; bu sürede çok yağlı süt sayesinde ağırlığını hızla artırıp soğuğa karşı yalıtım kazanır.'),
  ('Güneydoğu Asya\'da yaşayan Dayak meyve yarasası hangi olağan dışı özelliği nedeniyle bilinir?', 'Erkeklerinin de süt üretebilmesi', ['Yumurta bırakması', 'Kış uykusunda doğurması', 'Kesesinde yavru taşıması'], 'Dayak meyve yarasasının erkeklerinde de işleyen meme bezleri gözlenmiştir; bu, doğal koşullarda erkek emzirmesinin bilinen nadir örneklerindendir.'),
  ('Avrupa yaban tavşanında, bir gebelik sürerken ikinci bir çiftleşmeyle farklı yaşta yeni embriyoların da oluşabildiği bildirilmiştir. Bu olaya ne ad verilir?', 'Süperfetasyon', ['Partenogenez', 'Gecikmeli tutunma', 'Poliembriyoni'], 'Süperfetasyonda gebelik sırasında ikinci bir döllenme gerçekleşir; böylece aynı dişide farklı gelişim evresinde embriyolar bulunur.'),
  ('Kuzey Amerika\'daki çayır tarla faresinin tek eşli, yakın akrabası dağ tarla faresinin ise çok eşli olması hangi araştırma alanında önemli bir model olmuştur?', 'Eş bağının sinirsel temelleri', ['Kış uykusunun mekanizması', 'Ekolokasyonun evrimi', 'Kürk renginin kalıtımı'], 'Bu iki türün karşılaştırılması, oksitosin ve vazopressin reseptörlerinin beyindeki dağılımının eş bağı oluşumunda rol oynadığını göstermiştir.'),
  ('Uganda kobu gibi bazı antiloplarda erkeklerin küçük bir alanda toplanıp sergileme yaptığı ve dişilerin bu alana gelip eş seçtiği çiftleşme düzenine ne ad verilir?', 'Lek', ['Harem', 'Tek eşlilik', 'Çok kocalılık'], 'Lekte erkekler kaynak savunmaz; yalnızca sergileme yaptıkları küçük alanları korur. Dişiler gelir, erkekleri karşılaştırır ve seçtikleriyle çiftleşip ayrılır.'),
  ('Türkiye\'nin bozkırlarında yaşayan, sırtı sarı-kahverengi alacalı, yüzünde siyah-beyaz maske bulunan ve tehlikede kuyruğunu kaldırıp kötü koku salgılayan sansargil hangisidir?', 'Alaca sansar', ['Kaya sansarı', 'Avrupa porsuğu', 'Su samuru'], 'Alaca sansar (Vormela peregusna) gösterişli deseniyle uyarı verir; tehdit altında kuyruğunu sırtına kaldırıp anal bezlerinden kötü kokulu salgı çıkarır.'),
  ('Oligosen döneminde Asya\'da yaşamış, omuz yüksekliği beş metreyi bulan ve karada yaşamış en büyük memelilerden kabul edilen boynuzsuz gergedan akrabası hangisidir?', 'Paraceratherium', ['Megatherium', 'Glyptodon', 'Deinotherium giganteum'], 'Paraceratherium (Indricotherium) gergedanların boynuzsuz bir akrabasıdır; ağaçların üst dallarından yaprak koparan dev bir otçuldu.'),
  ('Yaklaşık 50 milyon yıl önce bugünkü Pakistan\'da yaşamış, kurt boyutunda bir kara hayvanı olan ama kulak kemiklerinin yapısı nedeniyle balinaların atası sayılan memeli hangisidir?', 'Pakicetus', ['Basilosaurus', 'Megalodon', 'Mosasaurus'], 'Pakicetus dört bacaklı bir kara memelisiydi; kafatasındaki kalın kulak kemiği yapısı onu balinalarla ilişkilendirir.'),
  ('Adı \'yürüyen ve yüzen balina\' anlamına gelen ve hem karada yürüyüp hem suda yüzebilen bir ara biçim olarak kabul edilen fosil memeli hangisidir?', 'Ambulocetus', ['Pakicetus', 'Dorudon', 'Paraceratherium'], 'Ambulocetus büyük arka ayakları ve timsah benzeri gövdesiyle hem karada hem suda hareket edebilen bir erken balina akrabasıydı.'),
  ('Alt çenesinden aşağıya ve geriye doğru kıvrılan fildişleri taşıyan soyu tükenmiş hortumlu hangisidir?', 'Deinotherium', ['Yünlü mamut', 'Mastodon', 'Paraceratherium'], 'Deinotherium\'un fildişleri üst çeneden değil alt çeneden çıkar ve aşağı doğru kıvrılırdı; bu dişleri dal çekip kabuk soymak için kullandığı düşünülür.'),
  ('Yaşamış en büyük keseli olarak bilinen ve Avustralya\'da buzul çağında yaşamış, gergedan boyutundaki otçul hangisidir?', 'Diprotodon', ['Thylacoleo', 'Tilasin', 'Dev kırmızı kanguru'], 'Diprotodon vombatların dev bir akrabasıdır; yaklaşık 40.000 yıl önceye kadar Avustralya\'da yaşamıştır.'),
  ('Miyosen döneminde Anadolu dahil Avrasya ve Afrika\'da yaygın olan, her ayağında üç parmak bulunan at akrabası hangisidir?', 'Hipparion', ['Eohippus', 'Equus', 'Okapi'], 'Hipparion ortadaki büyük parmağın iki yanında küçük yan parmaklar taşıyan, otlaklara uyum sağlamış bir at soyuydu; fosilleri Türkiye\'de de bol bulunur.'),
  ('Pullarıyla karıncayiyene benzeyen pangolinlerin, moleküler çalışmalara göre yaşayan en yakın akrabaları hangi gruptur?', 'Etçiller', ['Karıncayiyenler', 'Armadillolar', 'Kemirgenler'], 'Pangolinler kendi takımları (Pholidota) içinde yer alır; DNA verileri onların en yakın akrabasının etçiller olduğunu göstermiştir. Karıncayiyenlere benzerlikleri yakınsak evrimdir.'),
  ('Güneydoğu Asya ormanlarında yaşayan ve sincaba benzeyen ağaç sivri fareleri hakkında hangisi doğrudur?', 'Primatlara yakın ayrı bir takımdır', ['Kemirgenlerin bir familyasıdır', 'Gerçek sivri farelerin ağaçta yaşayan türüdür', 'Keseli memelilerdir'], 'Ağaç sivri fareleri (Scandentia) adlarına karşın sivri fare değildir; moleküler veriler onları primatlar ve kaguanlarla aynı büyük gruba yerleştirir.'),
  ('Plasentalı memelilerin moleküler sınıflandırmasında primatlar, kemirgenler ve tavşanımsılar aynı üst grupta toplanır. Bu bilgiye göre aşağıdaki çiftlerden hangisi birbirine daha yakın akrabadır?', 'İnsan ile fare', ['İnsan ile at', 'Fare ile kirpi', 'Tavşan ile kanguru'], 'Euarchontoglires üst grubu primatları, kemirgenleri ve tavşanımsıları içerir; at ve kirpi ise başka bir üst gruptadır, kanguru da keselidir. Bu yüzden fare insan araştırmalarında sık kullanılan bir modeldir.'),
  ('Yaşayan primatların en küçüğü olarak bilinen, yaklaşık 30 gram ağırlığındaki Madagaskar türü hangisidir?', 'Madam Berthe\'nin fare lemuru', ['Pigme marmoset', 'Filipin tarsiyesi', 'Halka kuyruklu lemur'], 'Madam Berthe\'nin fare lemuru yaklaşık 30 gram ağırlığıyla bilinen en küçük primattır; Güney Amerika\'daki pigme marmoset ise en küçük maymundur.'),
  ('Memeliler arasında en kısa gebelik sürelerinden birine sahip olan ve yavruları yaklaşık iki hafta sonra arı büyüklüğünde doğan hayvan hangisidir?', 'Virginia opossumu', ['Ev faresi', 'Avrupa yaban tavşanı', 'Kızıl tilki'], 'Virginia opossumunun gebeliği yaklaşık 12-13 gün sürer; yavrular çok küçük doğar ve gelişimini annenin kesesinde tamamlar.'),
  ('Kyoto\'daki araştırmalarda Ayumu adlı genç şempanzenin ekranda kısa süre görünen sayıların yerlerini hatırlamada çoğu insandan başarılı olması hangi yeteneği gösterir?', 'Görsel çalışma belleği', ['İşaret dili öğrenme', 'Ekolokasyonla yön bulma', 'Alet yapma ve kullanma'], 'Ayumu, ekranda bir an görünüp kaybolan sayıların yerini sırayla doğru işaretleyebilmiştir; bu, şempanzelerde çok güçlü bir anlık görsel bellek olduğunu düşündürür.'),
  ('Laboratuvarda bir sıçanın, saydam bir kapanın içinde sıkışmış başka bir sıçanı, karşılığında ödül olmadan kurtarmayı öğrenmesi hangi kavramla ilgili araştırmalarda kullanılmıştır?', 'Empati benzeri davranış', ['Kış uykusu döngüsü', 'Bölge savunması', 'Yapay seçilim'], 'Bu deneylerde sıçanlar kapanı açmayı öğrenmiş ve çoğu zaman yanında çikolata bulunsa bile önce arkadaşını kurtarmıştır; bu, kemirgenlerde empatiye benzer güdülerin olabileceğini düşündürür.'),
  ('Panthera cinsinde yer almasına karşın kükreyemeyen büyük kedi hangisidir?', 'Kar leoparı', ['Afrika aslanı', 'Jaguar', 'Sibirya kaplanı'], 'Kar leoparı aslan, kaplan, leopar ve jaguarla aynı cinstedir ama ses yapısı farklıdır; kükremez, daha çok soluma ve mırlamaya benzer sesler çıkarır.'),
  ('Bazı yetişkin erkek orangutanlarda yüzün iki yanında gelişen geniş yanak çıkıntılarına ne ad verilir ve neyle ilişkilidir?', 'Flanj; baskın ve olgun erkeklik', ['Kese; besin depolama işlevi', 'Sakal; yalnızca ileri yaş', 'Ossikon; boynuz dövüşleri'], 'Flanj adı verilen yanak çıkıntıları ve büyük gırtlak kesesi baskın erkeklerde gelişir; bazı erkekler yıllarca bu özellikleri geliştirmeden üreyebilir.'),
  ('Güney Amerika\'nın orman ve sulak alanlarında yaşayan, perdeli ayaklarıyla iyi yüzen ve sürü hâlinde avlanan küçük köpekgil hangisidir?', 'Çalı köpeği', ['Fennek', 'Rakun köpeği', 'Kızıl tilki'], 'Çalı köpeği kısa bacaklı, tıknaz bir köpekgildir; perdeli ayakları sayesinde suya rahatça girer ve gruplar hâlinde kemirgen avlar.'),
  ('Orta Asya bozkırlarında yaşayan manul (Pallas kedisi) diğer küçük kedilerin çoğundan hangi göz özelliğiyle ayrılır?', 'Yuvarlak göz bebekleri', ['Kırmızı renkli irisleri', 'Kapanmayan göz kapakları', 'Başın yanlarındaki gözleri'], 'Manulun göz bebekleri kasıldığında küçük yuvarlaklar biçiminde kalır; ev kedisi gibi çoğu küçük kedide ise dikey yarık biçimini alır.'),
  ('Memelilerde kalpten çıkan ana atardamar (aort) sola kıvrılarak yay yapar. Kuşlarda bu yay hangi yöne kıvrılır?', 'Sağa', ['Sola, memelilerdeki gibi', 'Hem sağa hem sola, iki yay olarak', 'Hiç kıvrılmadan düz iner'], 'Kuşlar ve memeliler dört odacıklı kalbi bağımsız olarak evrimleştirmiştir; memelilerde sol, kuşlarda sağ aort yayı korunmuştur. Sürüngenlerde ise iki yay vardır.'),
  ('Memelilerin büyük çoğunluğu belirli bir erişkin boyuna ulaştıktan sonra uzamayı bırakır; birçok sürüngen ise ömür boyu yavaşça büyür. Memelilerdeki bu durumun nedeni nedir?', 'Büyüme plaklarının kapanması', ['Kemiklerin içinin boşalması', 'Kasların büyümeyi durdurması', 'Derinin esnekliğini kaybetmesi'], 'Memelilerde uzun kemiklerin uçlarında büyüme plakları bulunur; ergenlik sonrası bu plaklar kemikleşip kapandığında boyca uzama durur.'),
  ('Memelilerin kafatası omurgayla iki eklem yumrusu üzerinden birleşir. Sürüngen ve kuşlarda bu yumru sayısı kaçtır?', 'Bir', ['İki', 'Üç', 'Dört'], 'Memeliler ve amfibilerde kafatası tabanında iki oksipital kondil bulunur; sürüngen ve kuşlarda ise tek kondil vardır.'),
  ('Orta ve Güney Amerika ormanlarında yaşayan, kavrayıcı kuyruğuyla dallara tutunan, uzun diliyle meyve ve nektar yiyen rakungil hangisidir?', 'Kinkaju', ['Koati', 'Güney Amerika tapiri', 'Aguti'], 'Kinkaju rakungiller familyasındandır ama görünüşü ve kavrayıcı kuyruğuyla maymunlara benzer; çiçeklerden nektar yediği için tozlaşmaya da katkı sağlar.'),
  ('Avustralya\'nın kurak bölgelerinde yaşayan, uzun tavşan kulaklarıyla tanınan ve yuvalarda yaşayan keseli hangisidir?', 'Bilbi', ['Kuoka', 'Numbat', 'Valabi'], 'Bilbi bir bandikut türüdür; büyük kulakları ısı atımına ve toprak altındaki böcekleri duymaya yardım eder, güçlü ön ayaklarıyla derin yuvalar kazar.'),
  ('Genom çalışmalarında koku alıcı gen sayısının memeliler arasında en yüksek bulunduğu hayvan hangisidir?', 'Afrika fili', ['Kan tazısı', 'Ev faresi', 'İnsan'], '2014\'te yapılan bir karşılaştırmada Afrika filinin yaklaşık 2000 işlevsel koku alıcı geni olduğu, bunun köpeğin iki katından, insanın ise beş katından fazla olduğu bulunmuştur.'),
  ('Toprak altında karanlıkta yaşayan kör farelerin uzun tünellerde yönlerini bulmasına yardım ettiği deneylerle gösterilen duyu hangisidir?', 'Manyetik alanı algılama', ['Renkleri ayırt etme', 'Ekolokasyonla yön bulma', 'Kızılötesi ışığı görme'], 'Laboratuvar deneylerinde kör farelerin yuvalarını ve tünel yönlerini Dünya\'nın manyetik alanına göre ayarladığı, manyetik alan değiştirildiğinde de yönelimlerinin değiştiği gözlenmiştir.'),
  ('Memelilerin doğrudan atalarını da içeren, köpek benzeri dişlere ve memelilere yaklaşan çene yapısına sahip sinapsit grubu hangisidir?', 'Sinodontlar', ['Pelikozorlar', 'İktiyozorlar', 'Pterozorlar'], 'Sinodontlar Permiyen sonu ve Triyas\'ta yaşamış, farklılaşmış dişleri ve gelişen ikincil damaklarıyla memelilere en çok yaklaşan sinapsitlerdir; memeliler bu gruptan türemiştir.'),
  ('Çin\'de bulunan Repenomamus fosilinin midesinde küçük bir dinozor yavrusunun kalıntılarının görülmesi hangi yaygın varsayımı sarsmıştır?', 'O dönem memelilerinin hep av olduğu', ['Dinozorların yalnızca bitkiyle beslendiği', 'Memelilerin Mezozoyik\'te hiç bulunmadığı', 'Dinozorların yumurta bırakmadığı'], 'Porsuk boyutundaki Repenomamus, bazı Mezozoyik memelilerinin dinozor yavrularını bile avlayabilecek kadar iri ve etçil olduğunu göstermiştir.'),
  ('Yaklaşık 100 milyon yılı aşkın süre yaşamış, kemirgenlere benzeyen dişleriyle bilinen ve soyu yaklaşık 35 milyon yıl önce tükenen memeli grubu hangisidir?', 'Multitüberkülatlar', ['Sinodontlar', 'Monotremler', 'Kreodontlar'], 'Multitüberkülatlar azı dişlerindeki çok sayıda tüberkül (çıkıntı) nedeniyle bu adı almıştır; memeli tarihinin en uzun süre yaşamış gruplarındandır ve muhtemelen kemirgenlerle rekabet sonucu yok olmuştur.'),
  ('Wyoming\'de bulunan yaklaşık 52 milyon yıllık Onychonycteris yarasa fosilinde uçmaya uygun kanatlar bulunduğu hâlde kulak yapısının gelişmiş ekolokasyona uygun olmaması neyi düşündürür?', 'Uçuşun ekolokasyondan önce geldiğini', ['Yarasaların önce yüzmeyi öğrendiğini', 'Ekolokasyonun kuşlardan geçtiğini', 'Yarasaların hiç uçmadığını'], 'Onychonycteris uçabilen ama kulak bölgesi gelişmiş ekolokasyon için yeterli görünmeyen bir yarasadır; bu bulgu uçuşun önce, karmaşık ekolokasyonun sonra geliştiği görüşünü destekler.'),
  ('Şili ve Arjantin ormanlarında yaşayan küçük bir keseli olan \'monito del monte\' hangi nedenle ilgi çeker?', 'Avustralya keselilerine yakın olması', ['Yumurta bırakan tek Amerika memelisi olması', 'Kanat çırparak uçabilen tek keseli olması', 'Ağzında hiç diş bulunmaması'], 'Monito del monte Güney Amerika\'da yaşasa da genetik olarak Avustralya keselilerinin bulunduğu kola daha yakındır; bu, keselilerin iki kıta arasındaki geçmiş bağlantısına işaret eder.'),
  ('Çin\'de bulunan yaklaşık 160 milyon yıllık Juramaia fosili memeli evrimi açısından neden önemlidir?', 'Plasentalı soyunun erken üyesi olması', ['Bilinen ilk uçan memeli olması', 'Bilinen en büyük Jura memelisi olması', 'Yumurtlayan memelilerin atası olması'], 'Juramaia, keselilerden ayrılan ve plasentalılara giden soyun erken bir temsilcisidir; bu, iki büyük memeli kolunun Jura döneminde ayrılmış olduğunu gösterir.'),
  ('Sığır vebası (rinderpest) 2011\'de dünyada tamamen ortadan kaldırıldığı ilan edilen hastalıktır. Bu hastalığın 19. yüzyıl sonunda Afrika\'ya girişi yaban hayatını nasıl etkilemişti?', 'Yabani çift toynaklıları kırdı', ['Yalnızca kedigilleri öldürdü', 'Yaban hayatına hiçbir etkisi olmadı', 'Filleri ve gergedanları yok etti'], 'Sığır vebası evcil sığırların yanı sıra yabani çift toynaklıları da kırıp geçirmiştir; aşı kampanyalarıyla hastalık bitirildikten sonra Serengeti\'de gnu ve manda sayıları belirgin biçimde artmıştır.'),
  ('Kuzey Amerika\'da geyiklerde görülen kronik yitim hastalığı ile sığırlardaki deli dana hastalığının ortak etkeni nedir?', 'Prionlar', ['Bakteriler', 'Mantar sporları', 'Bağırsak kurtları'], 'Her iki hastalık da beyinde birikerek sinir dokusunu bozan anormal prion proteinlerinden kaynaklanır; bu proteinler çevrede uzun süre bozulmadan kalabilir.'),
  ('Türkiye\'nin güney kıyılarındaki mağaralarda koloniler hâlinde yaşayan ve ülkemizdeki tek meyve yarasası olarak bilinen tür hangisidir?', 'Mısır meyve yarasası', ['Büyük nalburunlu yarasa', 'Uzun kulaklı yarasa', 'Vampir yarasa'], 'Mısır meyve yarasası (Rousettus aegyptiacus) Türkiye\'nin Akdeniz kıyılarında yaşar; meyve yarasaları arasında dil tıklatarak basit ekolokasyon yapabilen nadir türlerdendir.'),
  ('Güneydoğu Anadolu\'nun kurak bölgelerinde de yaşayan ve iri kulaklarıyla diğer kirpilerden ayrılan küçük kirpi türü hangisidir?', 'Kulaklı kirpi', ['Oklukirpi', 'Ak göğüslü kirpi', 'Tenrek'], 'Kulaklı kirpi (Hemiechinus auritus) kurak bozkır ve yarı çöllere uyumludur; büyük kulakları ısı atmasına yardım eder. Türkiye\'nin batı ve kuzeyinde ise daha çok ak göğüslü kirpi görülür.'),
  ('1992\'de Vietnam ile Laos sınırındaki ormanlarda bilim dünyasına tanıtılan ve 20. yüzyılın en şaşırtıcı büyük memeli keşiflerinden sayılan sığırgil hangisidir?', 'Saola', ['Okapi', 'Gaur', 'Takin'], 'Saola, uzun düz boynuzlarıyla antilobu andıran ama sığırlara yakın bir sığırgildir; çok az birey gözlenebilmiş, gizemli bir türdür.'),
  ('Doğal ortamlarında izlenen Afrika fillerinin günde ortalama ne kadar uyuduğu bulunmuştur?', 'Yaklaşık iki saat', ['Yaklaşık on iki saat', 'Yaklaşık sekiz saat', 'Hiç uyumazlar'], 'Takip cihazlarıyla izlenen yabani Afrika filleri günde ortalama yaklaşık iki saat uyumuş, bazen birkaç gün hiç uyumamıştır; bu, memeliler için kaydedilen en kısa uyku sürelerindendir.'),
  ('Dokuz bantlı armadillolar hangi insan hastalığına neden olan bakterinin doğal konağı olarak bilinir?', 'Cüzzam', ['Sıtma', 'Kuduz', 'Kolera'], 'Dokuz bantlı armadillo, cüzzam bakterisinin çoğalabildiği az sayıdaki hayvandandır; düşük vücut sıcaklığı bakterinin üremesine elverişlidir.'),
  ('Kunduzların su altında gözlerini koruyan ve aynı anda görmelerini sağlayan yapı hangisidir?', 'Saydam bir üçüncü göz kapağı', ['Gözlerin derinin altına gömülmesi', 'Gözlerin içe çekilmesi', 'Göz önündeki kıl perdesi'], 'Kunduzlarda göz küresinin üzerine yandan kayan saydam bir zar (niktitan zar) bulunur; bu zar su altında gözü korurken görmeyi büyük ölçüde sürdürür.'),
  ('Yer domuzunun (aardvark) takımına \'Tubulidentata\' adının verilmesinin nedeni nedir?', 'Dişlerinin tüpçüklü olması', ['Dilinin tüp biçiminde olması', 'Kulaklarının tüp gibi uzun olması', 'Yuvalarının tüp biçiminde olması'], 'Yer domuzunun dişleri mine içermez ve sıkıca dizilmiş ince tüpçüklerden oluşur; bu benzersiz yapı takıma adını vermiştir.'),
  ('Dişleri olmayan pangolinler yuttukları karınca ve termitleri nasıl öğütür?', 'Kaslı mide ve yutulan taşlarla', ['Dilleriyle ezerek', 'Avlarını sindirmeden dışarı atarak', 'Avlarını önce suda eriterek'], 'Pangolinlerin midesi kaslı bir öğütücü gibi çalışır; yutulan küçük taşlar ve mide duvarındaki keratin çıkıntılar besini ezer.'),
  ('Etiyopya yaylalarında yaşayan ve beslenmesinin büyük kısmını kemirgenler oluşturan, kızıl kürklü uzun bacaklı köpekgil hangisidir?', 'Etiyopya kurdu', ['Altın çakal', 'Afrika yaban köpeği', 'Yeleli kurt'], 'Etiyopya kurdu yalnızca Etiyopya\'nın yüksek dağlarında yaşar; çoğunlukla tek başına dev köstebek fareleri ve diğer kemirgenleri avlar.'),
];
